// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed parameters: actor (caller), deposit amount, and supplied unlockTime
    function testFuzz_property(address actor, uint256 amount, uint256 suppliedUnlock) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // bound amount to a reasonable range that still allows fuzzing wide values
        amount = bound(amount, 0, 10 ether);

        // give actor funds so they can send value
        vm.deal(actor, amount);
        // ensure we run at a specific block time window but allow wide range
        // keep current block.timestamp as baseline
        uint256 before = block.timestamp;

        // perform Put as the actor with fuzzed suppliedUnlock and amount
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(suppliedUnlock) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded, the invariant for the reference contract must hold:
        // acc.unlockTime >= block.timestamp  (i.e., never set in the past)
        // Read the stored Holder via autogenerated getter: Acc(actor).unlockTime is accessible
        if (ok) {
            // read unlockTime from contract storage via public mapping getter
            (uint256 unlockTime, uint256 balance) = c.Acc(actor);
            // single assertion: after a successful Put, stored unlockTime is >= current block.timestamp
            // This holds for the reference contract for all inputs, but the mutant that assigns
            // acc.unlockTime = suppliedUnlock can set unlockTime < block.timestamp for some inputs,
            // causing this assertion to fail on that mutant.
            assertTrue(unlockTime >= block.timestamp, "unlockTime must not be in the past after Put");
        } else {
            // If Put reverted, we do not assert the invariant (Put must succeed for the invariant to be set).
            // Still include a trivial assertTrue to satisfy single-assert requirement in all code paths by
            // asserting that ok == false implies true (no-op). The main distinguishing assertion is above.
            assertTrue(!ok);
        }
    }
}

