pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor (who calls Put), amount sent, and the provided _unlockTime.
    // General rule: after Put returns, c.Acc(actor).unlockTime >= block.timestamp.
    function testFuzz_property(address actor, uint256 amount, uint256 providedUnlock) public {
        // Keep actor non-zero
        vm.assume(actor != address(0));
        // bound the amount to a reasonable range but wide enough to include 0 and large values
        amount = bound(amount, 0, 10 ether);
        // bound providedUnlock to a wide range including past and future timestamps
        providedUnlock = bound(providedUnlock, 0, type(uint256).max);

        // Fund the actor so they can send value
        vm.deal(actor, amount + 1 ether);

        // Make the call as the actor sending `amount` wei
        vm.prank(actor);
        // perform the payable call; wrap in try/catch to ensure we only assert after call completes
        bool ok;
        try c.Put{value: amount}(providedUnlock) {
            ok = true;
        } catch {
            // If Put reverted, we consider the property vacuously true for that input (we only assert state after successful Put)
            ok = false;
        }

        if (ok) {
            // Read the stored unlockTime via the public mapping getter
            (, uint256 storedUnlock) = c.Acc(actor);
            // Assert the general invariant the reference implementation always maintains
            assertTrue(storedUnlock >= block.timestamp);
        } else {
            // If Put reverted, still satisfy the test by asserting true (no state change to check)
            assertTrue(true);
        }
    }
}

