pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor and desired unlockTime (uint256). We let the fuzzer vary both.
    function testFuzz_property(address actor, uint256 _unlockTime) public {
        // keep actor non-zero to be a valid caller
        vm.assume(actor != address(0));

        // Give the actor some ETH so they can call Put
        uint256 deposit = 1 ether; // keep deposit equal to MinSum so Put affects state
        vm.deal(actor, deposit);

        // 1) First, actor calls Put with a large future unlockTime to set a future unlockTime
        uint256 future = block.timestamp + 7 days;
        vm.prank(actor);
        c.Put{value: deposit}(future);

        // Read stored unlockTime after first Put
        uint256 before = c.Acc(actor).unlockTime;

        // sanity: before should be >= block.timestamp in reference implementation
        // but we do not assert that here; we only rely on the monotonic/non-decreasing rule below.

        // 2) Now actor calls Put again with fuzzed _unlockTime and small payment (still nonzero)
        // ensure actor has funds for the call
        vm.deal(actor, 1 wei);
        vm.prank(actor);
        c.Put{value: 1 wei}(_unlockTime);

        // Read stored unlockTime after second Put
        uint256 after = c.Acc(actor).unlockTime;

        // GENERAL RULE (single assert): After a Put, the stored unlockTime for that account
        // must not be strictly less than the previous stored unlockTime unless the previous
        // value was already in the past; equivalently, Put cannot reduce a future unlockTime to the past.
        // We express this as: if 'before' was >= block.timestamp then after must be >= before.
        // This holds for the reference contract for all inputs; the mutant that assigns acc.unlockTime = _unlockTime
        // can set 'after' < before for some fuzzed _unlockTime, causing this assertion to fail.
        if (before >= block.timestamp) {
            assertTrue(after >= before);
        } else {
            // when before was already in the past, we cannot demand non-decrease relative to block.timestamp
            // but we still assert that after is not an arbitrary unrelated state (this branch keeps domain wide)
            assertTrue(true);
        }
    }
}

