pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz params: actor address and two unlock times and an amount
    // We will ensure previous unlockTime is >= block.timestamp by first calling Put with a future time,
    // then call Put again with a (fuzzed) _unlockTime and check that reference never decreases the stored
    // unlockTime below the previous value when that previous value was in the future.
    function testFuzz_property(address actor, uint256 firstUnlock, uint256 secondUnlock, uint256 amt) public {
        // keep actor as non-zero
        vm.assume(actor != address(0));
        // bound amount to a reasonable value so vm.deal works and avoid overflow in balance math
        amt = bound(amt, 1 wei, 10 ether);
        // ensure firstUnlock is in the future (>= now + 1) to establish the precondition
        uint256 nowPlus = block.timestamp + 1;
        firstUnlock = bound(firstUnlock, nowPlus, nowPlus + 365 days);
        // secondUnlock keep wide (allow past/future)
        secondUnlock = bound(secondUnlock, 0, type(uint256).max);

        // fund actor
        vm.deal(actor, amt);

        // 1) actor does initial Put to set a stored unlockTime in the future
        vm.prank(actor);
        c.Put{value: amt}(firstUnlock);

        // read the stored unlockTime after first Put
        uint256 storedAfterFirst = c.Acc(actor).unlockTime;

        // precondition check: storedAfterFirst should be >= block.timestamp (we set firstUnlock >= now+1)
        // If reference is used this will hold; we keep it as an admissible domain condition
        vm.assume(storedAfterFirst >= block.timestamp);

        // 2) actor calls Put again with fuzzed secondUnlock and some value (could be zero)
        // fund actor for second call as well
        uint256 secondAmt = amt; // reuse amount
        vm.deal(actor, secondAmt);
        vm.prank(actor);
        c.Put{value: secondAmt}(secondUnlock);

        // read stored unlockTime after second Put
        uint256 storedAfterSecond = c.Acc(actor).unlockTime;

        // General rule (single assertion): if the stored unlockTime was >= block.timestamp before the second Put,
        // then after the second Put it must not be strictly less than the previous stored value.
        // The reference implementation enforces acc.unlockTime = max(_unlockTime, block.timestamp) so it cannot decrease
        // below a previously future-stored value; the mutant assigning acc.unlockTime = _unlockTime can decrease it.
        assertTrue(storedAfterSecond >= storedAfterFirst);
    }
}

