pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint64 unlockOffset, uint128 deposit) public {
        // Keep domains wide but sensible
        vm.assume(actor != address(0));
        // deposit must be at least 1 wei and bounded to avoid overflow in test harness operations
        deposit = deposit == 0 ? 1 : deposit;
        // compute target unlock time relative to current time
        uint256 nowt = block.timestamp;
        // unlockOffset is a delta added to now; allow it to be large so fuzzer can hit unlock > now
        uint256 requestedUnlock = nowt + uint256(unlockOffset);

        // fund actor and perform Put as actor
        vm.deal(actor, deposit);
        vm.prank(actor);
        // call Put with the fuzzed requestedUnlock and value deposit
        c.Put{value: deposit}(requestedUnlock);

        // single universal assertion: after Put, the stored unlockTime is >= max(requestedUnlock, block.timestamp_at_call)
        // We cannot read the exact block.timestamp at the call here; but because we invoked Put in the same tx,
        // block.timestamp has not advanced. So require that c.Acc(actor).unlockTime >= requestedUnlock.
        // This holds for the reference (which sets to max(requestedUnlock, block.timestamp)) for all inputs,
        // and is violated by the mutant when requestedUnlock > block.timestamp.

        (uint256 accUnlock, ) = c.Acc(actor);
        assertTrue(accUnlock >= requestedUnlock);
    }
}

