import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: depositor address and an unlockTime candidate (uint256)
    function testFuzz_property(address depositor, uint256 unlockTime) public {
        // keep depositor non-zero to be a valid caller
        vm.assume(depositor != address(0));
        // bound unlockTime to a reasonably large range (still keep wide)
        unlockTime = bound(unlockTime, 0, type(uint64).max);

        // ensure depositor has some ether to send
        uint256 deposit = 1 ether;
        vm.deal(depositor, deposit);

        // record block timestamp before the call
        uint256 before = block.timestamp;

        // make the call from depositor, sending 1 ether
        vm.prank(depositor);
        c.Put{value: deposit}(unlockTime);

        // Read stored holder info via generated getter Acc(depositor)
        (uint256 storedUnlockTime, uint256 storedBalance) = c.Acc(depositor);

        // GENERAL RULE: after Put, storedUnlockTime is at least the pre-call timestamp
        // and if the provided unlockTime was in the future (> before) then storedUnlockTime >= provided unlockTime.
        // This holds for reference C for all inputs, but the mutant that forces unlockTime=block.timestamp
        // can violate the second part when unlockTime > before. We assert the conjunction so the mutant fails
        // for some fuzzed inputs where unlockTime > before.
        bool rule = (storedUnlockTime >= before) && (unlockTime <= before || storedUnlockTime >= unlockTime);

        assertTrue(rule);
    }
}

