pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: depositor address and a future unlock time (big uint)
    function testFuzz_property(address depositor, uint256 futureUnlock) public {
        // keep depositor as a non-zero address and not the test contract (admissible domain)
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(this));

        // ensure futureUnlock is indeed in the future relative to current block.timestamp
        // bound it to be at least block.timestamp+1 to avoid equality
        uint256 unlock = bound(futureUnlock, block.timestamp + 1, type(uint256).max);

        // deposit some positive amount so Put will record balance and set unlockTime
        uint256 amt = 1 ether;
        vm.deal(depositor, amt);
        vm.startPrank(depositor);
        // call Put with a future unlock time and value
        (bool ok, ) = address(c).call{value: amt}(abi.encodeWithSignature("Put(uint256)", unlock));
        vm.stopPrank();

        // Read the stored Holder via the public mapping getter: Acc(address) returns (unlockTime, balance)
        (uint256 storedUnlockTime, uint256 storedBalance) = c.Acc(depositor);

        // The universal property: if caller provided a future unlock (> block.timestamp at call time) and sent >0,
        // then the stored unlockTime equals the provided future unlock time. This holds in reference C for ALL such inputs.
        // We assert that property; the mutant that forces unlockTime = block.timestamp will fail for some inputs.
        assertTrue(storedBalance >= amt && storedUnlockTime == unlock);
    }
}

