pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: actor (who calls Put) and two values v1 and v2
    // We use two puts to observe that second Put increases balance by at least the second msg.value
    function testFuzz_property(address actor, uint96 v1, uint96 v2) public {
        // keep actor nonzero and amounts in a reasonable range, but wide
        vm.assume(actor != address(0));
        uint256 amount1 = uint256(v1);
        uint256 amount2 = uint256(v2);
        // ensure amounts are >= 1 wei (admissible) and not absurdly large to avoid overflow in test harness
        if (amount1 == 0) { amount1 = 1; }
        if (amount2 == 0) { amount2 = 1; }

        // prepare actor with funds
        vm.deal(actor, amount1 + amount2 + 1 ether);

        // first deposit
        vm.prank(actor);
        c.Put{value: amount1}(0);

        // read balance after first put
        (uint256 balAfter1, ) = (uint256(0), uint256(0)); // placeholder to satisfy structless unpack? not used
        // use public getter Acc to read Holder.balance: Acc returns (unlockTime, balance)
        (uint256 ut1, uint256 balance1) = c.Acc(actor);
        // sanity: balance1 should be >= amount1 for correct contract

        // second deposit
        vm.prank(actor);
        c.Put{value: amount2}(0);

        // read balance after second put
        (uint256 ut2, uint256 balance2) = c.Acc(actor);

        // The universal property: after the second Put, the balance increased by at least amount2
        // i.e., balance2 >= balance1 + amount2
        // For the correct contract this holds for all inputs; the mutant that resets balance to msg.value will violate it when balance1 > 0
        assertTrue(balance2 >= balance1 + amount2);
    }
}

