pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: actor address and deposit amount
    function testFuzz_property(address actor, uint96 amt) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // bound amount to a reasonable range and ensure non-zero deposit (so Put executes meaningful branch)
        uint256 value = bound(uint256(amt), 1, 10 ether);

        // fund the actor so they can send value
        vm.deal(actor, value);

        // record pre-call balance of the holder via public getter Acc(actor).balance
        // Acc is a public mapping to a struct; solidity auto-generates Acc(address) returning (uint unlockTime, uint balance)
        (uint preUnlock, uint preBal) = c.Acc(actor);

        // Make the call from actor with the fuzzed value
        vm.prank(actor);
        // call Put with an arbitrary unlockTime (0 is acceptable because fallback uses Put(0) and Put handles it)
        // wrap in try/catch to observe call success (but Put shouldn't revert for valid deposits)
        bool ok;
        try c.Put{value: value}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // Only consider cases where the call succeeded (reference should accept deposits)
        vm.assume(ok);

        // After call, read the holder state
        (uint postUnlock, uint postBal) = c.Acc(actor);

        // General property: after a Put that succeeds, the stored balance is at least the deposited msg.value
        // This holds for the reference implementation for all inputs, but the mutant that does `acc.balance = msg.value`
        // can make postBal < value when previous balance > value, so the mutant will fail this assertion for some inputs.
        assertTrue(postBal >= value);
    }
}

