pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: depositor address and deposit amount, plus an initial deposit amount
    function testFuzz_property(address depositor, uint96 initialDeposit, uint96 secondDeposit, uint256 unlockTime) public {
        // Keep depositor non-zero and amounts reasonably bounded and distinct to exercise the overwrite bug
        vm.assume(depositor != address(0));
        // bound deposits to fit in uint256 and be realistic (avoid extremely large values)
        uint256 d1 = bound(uint256(initialDeposit), 0, 10 ether);
        uint256 d2 = bound(uint256(secondDeposit), 0, 10 ether);

        // fund the depositor EOA so it can send ETH
        vm.deal(depositor, d1 + d2 + 1 ether);

        // First deposit by depositor: record pre and post balances
        vm.prank(depositor);
        c.Put{value: d1}(unlockTime);

        // Read recorded balance after first deposit
        uint256 balAfterFirst = c.Acc(depositor).balance;

        // Second deposit
        vm.prank(depositor);
        c.Put{value: d2}(unlockTime);

        // Read recorded balance after second deposit
        uint256 balAfterSecond = c.Acc(depositor).balance;

        // The general correct-rule: the second recorded balance must equal the first recorded balance plus the second deposit
        // We assert this general invariant: balAfterSecond >= balAfterFirst + d2 (we use equality originally intended by contract, but >= is safe if other logic could add value)
        // Use equality to precisely capture the intended increment behavior of the reference implementation.
        assertTrue(balAfterSecond == balAfterFirst + d2);
    }
}

