pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: depositor (address) and amount (uint256) and an initial funding amount
    // The general rule: after Put, stored balance increased by exactly msg.value
    function testFuzz_property(address depositor, uint256 initial, uint256 deposit) public {
        // keep values in reasonable on-chain ranges but wide enough
        deposit = bound(deposit, 0, 5 ether);
        initial = bound(initial, 0, 5 ether);
        // ensure depositor is not zero address to allow vm.prank to work as expected
        vm.assume(depositor != address(0));

        // fund depositor for both initial and deposit
        vm.deal(depositor, initial + deposit + 1 ether);

        // first, if initial > 0, make an initial deposit to set a prior balance
        if (initial > 0) {
            vm.prank(depositor);
            c.Put{value: initial}(0);
        }

        // read previous balance via public getter Acc returns tuple (unlockTime,balance)
        (, uint256 balBefore) = c.Acc(depositor);

        // perform the fuzzed deposit
        bool ok;
        vm.prank(depositor);
        try c.Put{value: deposit}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract never reverts on Put (it only has a require that always holds for non-overflow in ^0.8)
        // and the state update must satisfy: newBalance == balBefore + deposit
        (, uint256 balAfter) = c.Acc(depositor);

        // single assertion: for all admissible inputs the increment property holds
        assertTrue(ok && balAfter == balBefore + deposit);
    }
}

