pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    // fuzz parameters: actor address and a non-zero initial deposit (so prior balance becomes non-zero),
    // and a follow-up deposit amount (which we allow to be zero to trigger overwrite bug)
    function testFuzz_property(address actor, uint256 initDeposit, uint256 followDeposit) public {
        // keep actor usable and amounts in reasonable bounds
        vm.assume(actor != address(0));
        initDeposit = bound(initDeposit, 1 wei, 10 ether); // ensure initial deposit is non-zero
        followDeposit = bound(followDeposit, 0 wei, 10 ether);

        // Fund the actor
        vm.deal(actor, initDeposit + followDeposit + 1 ether);

        // actor makes initial deposit to create a non-zero prior balance
        vm.prank(actor);
        c.Put{value: initDeposit}(0);

        // read prior balance via public getter mapping Acc
        uint256 prior = c.Acc(actor).balance;
        // ensure prior is non-zero as intended
        assertTrue(prior >= initDeposit);

        // actor makes follow-up deposit (can be zero)
        vm.prank(actor);
        c.Put{value: followDeposit}(0);

        // single assertion: for the correct contract, if followDeposit == 0 then balance must remain equal to prior
        // (the reference increments by msg.value so zero deposit preserves prior); the mutant that sets acc.balance = msg.value
        // will set balance to 0 when followDeposit == 0, breaking this
        uint256 after = c.Acc(actor).balance;
        if (followDeposit == 0) {
            assertTrue(after == prior);
        } else {
            // if followDeposit > 0 both ref and mutant may differ in other ways; still assert a trivial true to keep single assert
            assertTrue(true);
        }
    }
}

