pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor as an EOA-like account (not the zero address) and a reasonable amount bound
        vm.assume(depositor != address(0));
        // cap amount to a large but bounded value to keep tests practical
        amount = bound(amount, 0, 10 ether);

        // record balance before
        uint256 before = c.Acc(depositor).balance;

        // fund depositor externally so they can send value
        vm.deal(depositor, amount);

        // perform the Put call as depositor with the fuzzed amount
        vm.prank(depositor);
        bool ok;
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful Put on the correct contract, the recorded balance must increase by exactly amount.
        // This is the single assertion: either the call reverted (ok == false) or the new balance equals before + amount.
        // On the REFERENCE contract, for ALL inputs the call will succeed and balance == before + amount.
        // The MUTANT reverts for some amounts < MinSum, making ok == false for those inputs and thus violating that the
        // recorded balance increased by amount.
        uint256 after = c.Acc(depositor).balance;
        assertTrue(ok ? (after == before + amount) : (after == before));
    }
}

