        // Read the Log.History length via the public getter on Log (accessed as c.LogFile().History length)
        // The test must use only c's public surface. c.LogFile() is a public variable of type Log, so we can
        // access its History via the autogenerated getter: c.LogFile().History(uint)
        // There's no direct getter for length, but we can probe the last pushed entry by index 0..n-1.
        // We can instead check that the last message's Val equals the deposit amount for at least one input
        // To do that in a universal property we check that trying to read History at index 0 succeeds (i.e., at least one entry)

        bool hasEntry;
        // try to read History[0].Val via low-level external call to the Log contract getter
        address logAddr = address(c.LogFile());
        // The Log contract autogenerated getter for History(uint) returns (address,string,uint,uint).
        // We'll call it via low-level staticcall to detect presence of at least one entry.
