        // Therefore instead of having actor be depositor, we make actor deposit then have malicious contract call Collect.

        // Rework: actor deposits, then we make the malicious contract call Collect to receive funds (so msg.sender = malicious)
        // To enable that, actor must have deposited funds under Acc[malicious] — but Acc is keyed by msg.sender at Put time.
        // So we need the malicious contract itself to be the depositor. Thus earlier deposit must be performed by the malicious contract.

        // Reset and perform correct setup: have either this test contract (EOA) or malicious contract deposit to c.
        // We re-deploy clean c to ensure deterministic state
        c = new C(address(this));
        vm.deal(address(mal), 100 ether);
        vm.deal(address(this), 100 ether);

        // Choose depositor as either malicious contract or this test contract (EOA)
        address depositor = recipient; // recipient chosen above: if useMalicious then malicious, else this

        // depositor makes a Put deposit of amount
        if (amount == 0) amount = 1 ether; // ensure some deposit to potentially meet MinSum
        amount = bound(amount, 1 ether, 100 ether); // ensure >= MinSum

        // fund depositor already done for mal and this; now have depositor call Put
        if (depositor == address(mal)) {
            // have the malicious contract call Put
            mal.doDeposit{value: amount}(address(c), amount);
        } else {
            // this test contract calls Put
            c.Put{value: amount}(block.timestamp - 1);
        }

        // Now have the depositor attempt to Collect the same amount
        bool ok;
        if (depositor == address(mal)) {
            // malicious contract will call Collect; its receive will consume lots of gas if send is used
            try mal.doCollect(address(c), amount) {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // EOA (this) calls Collect
            try c.Collect{value: 0}(amount) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // The universal property: on the reference C (which uses call and forwards gas) Collect never reverts for
        // admissible inputs where depositor has balance >= MinSum and block.timestamp > unlockTime, so ok should be true.
        // The mutant that uses send can cause the send to fail when the recipient's receive consumes >2300 gas,
        // so for the adversarial depositor (malicious) there exists an input where ok == false. Our single assert reads c via ok.
        assertTrue(ok);
    }
}

// Minimal malicious receiver that consumes more than 2300 gas in receive to cause send to fail
contract MaliciousReceiver {
    // allow this contract to deposit into C
    function doDeposit(address caddr, uint256 amt) public payable {
        C(caddr).Put{value: amt}(block.timestamp - 1);
    }

    // call Collect on C to attempt to withdraw funds to this contract (msg.sender will be this contract)
    function doCollect(address caddr, uint256 amt) public {
        C(caddr).Collect{value: 0}(amt);
    }

    // receive consumes lots of gas
    receive() external payable {
        // burn gas with a loop
        uint256 sum = 0;
        for (uint i = 0; i < 2000; i++) {
            sum += i;
        }
        // use sum to prevent optimization
        if (sum == 0) {
            // no-op
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor address and withdrawal amount
    function testFuzz_property(address depositor, uint256 depositAndWithdraw) public {
        // Keep depositor non-zero and bound amount to reasonable range
        vm.assume(depositor != address(0));
        uint256 amt = bound(depositAndWithdraw, 1 wei, 5 ether);

        // Deploy a reverter helper that will revert on receive to simulate failing external call
        Reverter rev = new Reverter();

        // Give depositor enough ETH to deposit
        vm.deal(depositor, amt + 1 ether);
        // depositor deposits into c via fallback which calls Put(0)
        vm.prank(depositor);
        (bool okPut,) = address(c).call{value: amt}("" );
        require(okPut, "deposit failed");

        // Ensure depositor's stored balance inside c is at least MinSum if amt big enough.
        // Warp time forward to allow Collect (unlockTime set to block.timestamp in Put(0)).
        vm.warp(block.timestamp + 1);

        // Now we want depositor to collect 'amt' but route the call so that the low-level send goes to Reverter,
        // so the external transfer will revert when called by c in the reference — causing reference to revert
        // and thus NOT deduct its internal balance; the mutant swallows failure and will deduct internal balance
        // despite external transfer failing. To achieve this, we make depositor be the address that is also the
        // callee for c.call => c will call msg.sender.call, so we must have msg.sender be the Reverter.
        // Use vm.prank to set msg.sender to the Reverter's address while calling c.Collect.

        // Make sure the depositor we used to fund the account matches the Reverter address so msg.sender is the
        // failing contract. To do that, we transfer the deposited balance ownership: deploy a proxy EOA-like helper
        // is not possible, but we can instead deposit from the Reverter by funding it and calling from it.
        // So instead, redo: fund rev and deposit from rev, then attempt Collect from rev.

        // Reset: redeploy fresh c to ensure deterministic sequence (we must not redeclare c), so instead revert actions
        // Achieve the intended scenario by deploying a new transient depositor contract that forwards deposit and then
        // later becomes the msg.sender for Collect. We'll use Reverter itself to deposit (it has payable fallback).

        // Fund Reverter and have it deposit the amt into c
        vm.deal(address(rev), amt + 1 ether);
        // From EOA 'depositor' cause rev to call c and deposit amt: call a function on rev that forwards deposit
        rev.forwardDeposit{value: amt}(address(c));

        // Warp time a bit
        vm.warp(block.timestamp + 1);

        // Now call Collect as if from rev (so msg.sender == rev). This will trigger c to call rev (msg.sender.call),
        // which in the reference will revert causing the whole Collect to revert and NOT reduce Acc[rev].balance.
        // In the mutant, Collect will swallow the failed send and will have already decreased Acc[rev].balance.

        bool okCollect;
        // perform the call and catch success/failure
        vm.prank(address(rev));
        try c.Collect(amt) {
            okCollect = true;
        } catch {
            okCollect = false;
        }

        // The universal property we assert: If Collect returned (okCollect == true) then the contract's ETH balance decreased by amt
        // However, to keep a single assertion that is true for reference for all inputs and false for mutant for some input,
        // we assert that NOT(okCollect) || address(c).balance + (okCollect ? 0 : 0) >= 0 — but must be a concrete property.
        // Simpler universal property: After attempt to Collect by a caller whose fallback reverts, the contract's stored balance for that caller
        // is equal to its on-chain balance effect: for the reference, when the external call fails the entire call reverts, so stored balance remains unchanged.
        // So we assert: if the external call reverted (okCollect == false) then c.Acc(rev).balance == amt.

        // Read stored balance for rev via public getter (Acc is public mapping returning (unlockTime,balance))
        (, uint storedBal) = c.Acc(address(rev));

        // Exactly one assertTrue as required: reference will always satisfy that when the external call reverted, stored balance was not decreased.
        assertTrue(okCollect || storedBal == amt);
    }
}

// Helper contract that reverts on receive/call and can forward deposit to C
contract Reverter {
    // allow receiving to then revert later on low-level call by reverting in fallback
    fallback() external payable { revert("revert in Reverter"); }
    receive() external payable { revert("revert in Reverter"); }

    // helper to forward a deposit to target C via its fallback (which triggers Put(0))
    function forwardDeposit(address target) external payable {
        // send to target so target's fallback() triggers
        (bool ok,) = target.call{value: msg.value}("");
        require(ok, "forward deposit failed");
    }
}
